query:
query($ids:[ID!]!){nodes(ids:$ids){... on Comment{
          __typename id createdAt updatedAt publishedAt lastEditedAt includesCreatedEdit editor{login url}
          userContentEdits(first:100){totalCount pageInfo{hasNextPage endCursor} nodes{id createdAt updatedAt editedAt editor{login url} deletedAt deletedBy{login url} diff}}
          ... on PullRequest{reviews{totalCount} comments{totalCount}}
          ... on Issue{comments{totalCount}}
          }} rateLimit{cost remaining resetAt}}
